ALTER TABLE "contract_commands" DROP CONSTRAINT "contract_commands_kind_check";--> statement-breakpoint
ALTER TABLE "contract_events" DROP CONSTRAINT "contract_events_metadata_check";--> statement-breakpoint
ALTER TABLE "contract_project_links" ADD COLUMN "created" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "contract_commands" ADD CONSTRAINT "contract_commands_kind_check" CHECK ((((((("contract_commands"."kind" = 'CREATE' AND "contract_commands"."result_quality_run_id" IS NULL) OR ("contract_commands"."kind" = 'RUN_QUALITY_CHECKS' AND "contract_commands"."result_quality_run_id" IS NOT NULL)) AND "contract_commands"."result_decision_id" IS NULL OR ("contract_commands"."kind" IN ('APPROVE','REJECT') AND "contract_commands"."result_quality_run_id" IS NULL AND "contract_commands"."result_decision_id" IS NOT NULL)) AND "contract_commands"."result_signature_id" IS NULL) OR ("contract_commands"."kind" = 'RECORD_SIGNATURE' AND "contract_commands"."result_quality_run_id" IS NULL AND "contract_commands"."result_decision_id" IS NULL AND "contract_commands"."result_signature_id" IS NOT NULL)) AND "contract_commands"."result_project_link_id" IS NULL) OR ("contract_commands"."kind" IN ('LINK_PROJECT','CREATE_PROJECT') AND "contract_commands"."result_quality_run_id" IS NULL AND "contract_commands"."result_decision_id" IS NULL AND "contract_commands"."result_signature_id" IS NULL AND "contract_commands"."result_project_link_id" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "contract_events" ADD CONSTRAINT "contract_events_metadata_check" CHECK ((jsonb_typeof("contract_events"."metadata") = 'object' AND "contract_events"."metadata"->>'contractId' = "contract_events"."contract_id"::text AND (("contract_events"."action" = 'contract_project.linked' AND ("contract_events"."metadata" - ARRAY['contractId','projectId','created']::text[]) = '{}'::jsonb AND "contract_events"."metadata"->'created' IN ('false'::jsonb,'true'::jsonb) AND jsonb_typeof("contract_events"."metadata"->'projectId') = 'string') OR ("contract_events"."action" <> 'contract_project.linked' AND ("contract_events"."metadata" - ARRAY['contractId','contractVersionId','versionNumber','illustrativeReference','kind','origin','offerVersionId','pricingSnapshotId','provenance','ruleSetVersion','acknowledgedWarningCodes','evidenceKind']::text[]) = '{}'::jsonb AND "contract_events"."metadata"->>'kind' = 'CONTRACT' AND "contract_events"."metadata"->>'origin' = 'ACCEPTED_OFFER' AND "contract_events"."metadata"->>'provenance' = 'ILLUSTRATIVE' AND ("contract_events"."action" <> 'contract_version.signature_recorded' OR "contract_events"."metadata"->>'evidenceKind' = 'SIMULATED')))) IS TRUE);
--> statement-breakpoint
CREATE OR REPLACE FUNCTION guard_cp1_project_link_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c contracts%ROWTYPE;
BEGIN
 SELECT * INTO c FROM contracts WHERE workspace_id=NEW.workspace_id AND company_id=NEW.company_id AND id=NEW.contract_id;
 IF c.revision < NEW.result_revision OR NOT EXISTS(SELECT 1 FROM contract_commands WHERE workspace_id=NEW.workspace_id AND company_id=NEW.company_id AND result_contract_id=NEW.contract_id AND result_project_link_id=NEW.id AND kind=CASE WHEN NEW.created THEN 'CREATE_PROJECT' ELSE 'LINK_PROJECT' END AND opportunity_id=c.opportunity_id AND actor_workspace_membership_id=NEW.actor_workspace_membership_id AND created_at=NEW.linked_at) OR NOT EXISTS(SELECT 1 FROM contract_events WHERE workspace_id=NEW.workspace_id AND company_id=NEW.company_id AND contract_id=NEW.contract_id AND action='contract_project.linked' AND actor_workspace_membership_id=NEW.actor_workspace_membership_id AND actor_internal_user_id=NEW.actor_internal_user_id AND occurred_at=NEW.linked_at AND metadata=jsonb_build_object('contractId',NEW.contract_id::text,'projectId',NEW.project_id::text,'created',NEW.created)) THEN RAISE EXCEPTION 'Incomplete Contract Project link' USING ERRCODE='23514'; END IF;
 IF NEW.created AND NOT EXISTS(SELECT 1 FROM projects p JOIN project_creation_events e ON e.workspace_id=p.workspace_id AND e.company_id=p.company_id AND e.project_id=p.id WHERE p.workspace_id=NEW.workspace_id AND p.company_id=NEW.company_id AND p.id=NEW.project_id AND p.created_by_workspace_membership_id=NEW.actor_workspace_membership_id AND e.actor_workspace_membership_id=NEW.actor_workspace_membership_id) THEN RAISE EXCEPTION 'Incomplete Contract Project creation' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $$;

